int hgic_fwctrl_do_cmd(struct hgic_fwctrl *ctrl, u8 ifidx, u32 cmd_id, u8 *in, u32 in_len, u8 *out, u32 out_size)
{
    int ret = -1;
    struct sk_buff *skb  = NULL;
    struct sk_buff *resp = NULL;
    struct hgic_cmd_response receipt;
    unsigned long flags;

    if ((!in && in_len) || (!out && out_size)) {
        hgic_attach_error(-EINVAL, HGIC_ATTACH_COMMAND);
        return -EINVAL;
    }
    if(in_len > 2000){
        hgic_err("data len is too long\r\n");
        hgic_attach_error(-EINVAL, HGIC_ATTACH_COMMAND);
        return -EINVAL;
    }

    spin_lock_irqsave(&ctrl->lock, flags);
    if (ctrl->attach_task != current || ctrl->attach_command ||
        cmd_id != HGIC_CMD_GET_FW_INFO || ifidx != HGIC_WDEV_ID_STA ||
        in_len || !out || out_size != 24 || hgic_attach_failed()) {
        spin_unlock_irqrestore(&ctrl->lock, flags);
        hgic_attach_error(-EPERM, HGIC_ATTACH_COMMAND);
        return hgic_attach_failed();
    }
    ctrl->attach_command = true;
    spin_unlock_irqrestore(&ctrl->lock, flags);

    skb = hgic_alloc_ctrl_skb(ctrl, in_len);
    if (skb) {
        spin_lock_irqsave(&ctrl->lock, flags);
        ctrl->attach_skb = skb;
        spin_unlock_irqrestore(&ctrl->lock, flags);
        if (in && in_len > 0) {
            memcpy(skb->data, in, in_len);
            skb->data[in_len] = 0;
        }

        resp = hgic_fwctrl_send_cmd(ctrl, ifidx, cmd_id, skb, &receipt);
        if (resp) {
            spin_lock_irqsave(&ctrl->lock, flags);
            if (hgic_attach_failed())
                ret = hgic_attach_failed();
            else if (ctrl->receipt_error)
                ret = ctrl->receipt_error;
            else
                ret = hgic_ctrl_reply_copy(resp->data, resp->len, receipt.type,
                                          receipt.ifidx, receipt.opcode, receipt.cookie,
                                          out, out_size);
            spin_unlock_irqrestore(&ctrl->lock, flags);
            dev_kfree_skb_any(resp);
        } else if (hgic_attach_failed()) {
            ret = hgic_attach_failed();
        } else if (READ_ONCE(ctrl->receipt_error)) {
            ret = READ_ONCE(ctrl->receipt_error);
        }
        if (ret < 0) {
            hgic_attach_error(ret, HGIC_ATTACH_COPY);
        }
    } else {
        ret = -ENOMEM;
        hgic_attach_error(ret, HGIC_ATTACH_COMMAND);
    }
    return ret;

/* Caller holds lock. Poison all station waiters, not a later response chosen by
 * cookie alone. Boot/maintenance ownership is NOT qualified by this A1 change.
 */
static void hgic_fwctrl_bad_receipt(struct hgic_fwctrl *ctrl)
{
    struct hgic_cmd_response *resp;

    WRITE_ONCE(ctrl->receipt_error, -EPROTO);
    WRITE_ONCE(ctrl->bus->rx_failed, 1);
    hgic_attach_error(-EPROTO, HGIC_ATTACH_RX);
    list_for_each_entry(resp, &ctrl->pd_list, list) {
        if ((resp->type == HGIC_HDR_TYPE_CMD || resp->type == HGIC_HDR_TYPE_CMD2) && !resp->done) {
            resp->done = true;
            complete(&resp->cmpl);
        }
    }
}

/* USB/core ingress uses the same locked A1 waiter/copy-admission latch. */
void hgic_fwctrl_rx_error(struct hgic_fwctrl *ctrl)
{
    unsigned long flags;

    spin_lock_irqsave(&ctrl->lock, flags);
    hgic_fwctrl_bad_receipt(ctrl);
    spin_unlock_irqrestore(&ctrl->lock, flags);
}

static int hgic_fwctrl_rx_response(struct hgic_fwctrl *ctrl, struct sk_buff *skb)
{
    int find = 0;
    unsigned long flags;
    struct hgic_cmd_response *resp = NULL;
    int status;
    u16 cookie;

    spin_lock_irqsave(&ctrl->lock, flags);
    if (!hgic_ctrl_frame_valid(skb->data, skb->len)) {
        hgic_fwctrl_bad_receipt(ctrl);
        goto unlock;
    }
    cookie = get_unaligned((const u16 *)(skb->data + 6));
    list_for_each_entry(resp, &ctrl->pd_list, list) {
        if (resp->cookie == cookie) {
            /* Duplicate/replayed completion can never replace the first skb. */
            if (resp->done)
                goto unlock;
            if (resp->type == HGIC_HDR_TYPE_CMD || resp->type == HGIC_HDR_TYPE_CMD2) {
                if (ctrl->receipt_error ||
                    hgic_ctrl_reply_status(skb->data, skb->len, resp->type,
                                           resp->ifidx, resp->opcode, resp->cookie,
                                           &status)) {
                    hgic_fwctrl_bad_receipt(ctrl);
                    goto unlock;
                }
                /* A valid associated signed failure is observed here, before
                 * publishing the response/waking its waiter. Preserve the
                 * first response and earlier error; do not call bad_receipt
                 * or copy negative-response payload. Lock order is the
                 * existing FWCTRL lock -> attach-receipt lock.
                 */
                if (status < 0)
                    hgic_attach_error(status, HGIC_ATTACH_COMMAND);
            }
            resp->skb = skb;
            resp->done = true;
            complete(&resp->cmpl);
            find = 1;
            break;
        }
    }
    if (!find)
        hgic_fwctrl_bad_receipt(ctrl); /* unknown/late association: no future TX */
unlock:
    spin_unlock_irqrestore(&ctrl->lock, flags);
    if (!find) {
        dev_kfree_skb_any(skb);
    }
    return 0;
}

struct sk_buff *hgic_fwctrl_send_data(struct hgic_fwctrl *ctrl, struct sk_buff *skb, struct hgic_cmd_response *resp, u32 timeout)
{
    unsigned long flags;
    struct hgic_ctrl_hdr *hdr;

    if (!skb || !resp || skb->len != sizeof(struct hgic_ctrl_hdr) ||
        resp->cookie > HGIC_TX_COOKIE_MASK) {
        hgic_attach_error(-EPERM, HGIC_ATTACH_COMMAND);
        dev_kfree_skb_any(skb);
        return NULL;
    }
    hdr = (struct hgic_ctrl_hdr *)skb->data;
    resp->type = hdr->hdr.type;
    resp->ifidx = hdr->hdr.ifidx;
    resp->opcode = HDR_CMDID(hdr);
    /* Direct boot/OTA/BT/tool callers cannot borrow init's command permission. */

    init_completion(&resp->cmpl);
    spin_lock_irqsave(&ctrl->lock, flags);
    if (ctrl->receipt_error || hgic_attach_failed() || ctrl->attach_task != current ||
        ctrl->attach_skb != skb || ctrl->attach_queued || !ctrl->attach_command ||
        timeout != HGIC_CMD_TIMEOUT || resp->type != HGIC_HDR_TYPE_CMD ||
        resp->ifidx != HGIC_WDEV_ID_STA ||
        resp->opcode != HGIC_CMD_GET_FW_INFO - HGIC_CMD_START ||
        le16_to_cpu(hdr->hdr.magic) != HGIC_HDR_TX_MAGIC ||
        le16_to_cpu(hdr->hdr.length) != skb->len ||
        le16_to_cpu(hdr->hdr.cookie) != resp->cookie || !ctrl->schedule) {
        spin_unlock_irqrestore(&ctrl->lock, flags);
        hgic_attach_error(-EPERM, HGIC_ATTACH_COMMAND);
        dev_kfree_skb_any(skb);
        return NULL;
    }
    ctrl->attach_queued = true;
    list_add(&resp->list, &ctrl->pd_list);
    spin_unlock_irqrestore(&ctrl->lock, flags);

    if (ctrl->txq.qlen > 4) {
        kfree_skb(skb_dequeue(&ctrl->txq));
        //hgic_err("ctrl txq full, drop data (%d)\r\n", ctrl->txq.qlen);
    }

    skb_queue_tail(&ctrl->txq, skb);
    ctrl->schedule(ctrl);
    if (timeout) {
        if (!wait_for_completion_timeout(&resp->cmpl, msecs_to_jiffies(timeout))) {
            hgic_attach_error(-ETIMEDOUT, HGIC_ATTACH_COMMAND);
            /* P3 must cancel owned UNSENT work; P2 does not free an async skb
             * or attach this stack waiter to it as a cancellation shortcut.
             */
        }
    }
    spin_lock_irqsave(&ctrl->lock, flags);
    list_del(&resp->list);
    spin_unlock_irqrestore(&ctrl->lock, flags);
#ifdef __RTOS__
    deinit_completion(&resp->cmpl);
#endif
    return resp->skb;
}

int hgic_fwctrl_get_fwinfo(struct hgic_fwctrl *ctrl, u8 ifidx, struct hgic_fw_info *info)
{
    int ret = 0;
    u8 retail[24] = {0};
    struct hgic_fw_info decoded = {0};
    if (!info) {
        hgic_attach_error(-EINVAL, HGIC_ATTACH_COMMAND);
        return -EINVAL;
    }
    /* Exact owned firmware2.1.0.1/stock REA layout, directly observed24
     * bytes. The newer mirror's app_version extends its C structure to28;
     * never substitute that host structure as the retail wire ABI.
     */
    ret = hgic_fwctrl_get_bytes(ctrl, ifidx, HGIC_CMD_GET_FW_INFO, retail, sizeof(retail));
    if (ret == sizeof(retail)) {
        if (!hgic_ctrl_retail_info_valid(retail, sizeof(retail))) {
            hgic_attach_error(-EPROTO, HGIC_ATTACH_COPY);
            return -EPROTO;
        }
        decoded.version = get_unaligned_le32(retail);
        decoded.svn_version = get_unaligned_le32(retail + 4);
        decoded.chip_id = get_unaligned_le16(retail + 8);
        decoded.cpu_id = get_unaligned_le16(retail + 10);
        memcpy(decoded.mac, retail + 12, 6);
        decoded.smt_dat = get_unaligned_le32(retail + 20);
        *info = decoded; /* no partial output or default-MAC fallback on reject */
    }
    return ret;
}

int hgic_fwctrl_attach_fwinfo(struct hgic_fwctrl *ctrl, struct hgic_fw_info *info)
{
    unsigned long flags;
    int error;
    spin_lock_irqsave(&ctrl->lock, flags);
    if (ctrl->attach_called || ctrl->attach_task || !ctrl->wq) {
        spin_unlock_irqrestore(&ctrl->lock, flags);
        hgic_attach_error(-EPERM, HGIC_ATTACH_COMMAND);
        return hgic_attach_failed();
    }
    error = hgic_attach_command_begin();
    if (error) {
        spin_unlock_irqrestore(&ctrl->lock, flags);
        return error;
    }
    ctrl->attach_called = true;
    ctrl->attach_task = current;
    spin_unlock_irqrestore(&ctrl->lock, flags);
    error = hgic_fwctrl_get_fwinfo(ctrl, HGIC_WDEV_ID_STA, info);
    spin_lock_irqsave(&ctrl->lock, flags);
    ctrl->attach_task = NULL;
    spin_unlock_irqrestore(&ctrl->lock, flags);
    if (error != 24)
        hgic_attach_error(error < 0 ? error : -EPROTO, HGIC_ATTACH_COPY);
    return error;
}

int hgic_fwctrl_attach_tx_admit(struct hgic_fwctrl *ctrl, struct sk_buff *skb)
{
    unsigned long flags;
    const struct hgic_ctrl_hdr *hdr;
    int error = 0;
    spin_lock_irqsave(&ctrl->lock, flags);
    /* Check local object identity before inspecting any purported wire header.
     * Consume this permission once. No async pointer to the stack waiter exists.
     */
    if (!skb || ctrl->attach_skb != skb || !ctrl->attach_queued ||
        ctrl->attach_tx_consumed || hgic_attach_failed() || ctrl->receipt_error ||
        skb_is_nonlinear(skb) || skb->len != sizeof(*hdr)) {
        error = -EPERM;
    } else {
        hdr = (const struct hgic_ctrl_hdr *)skb->data;
        if (hdr->hdr.type != HGIC_HDR_TYPE_CMD || hdr->hdr.ifidx != HGIC_WDEV_ID_STA ||
            le16_to_cpu(hdr->hdr.magic) != HGIC_HDR_TX_MAGIC ||
            le16_to_cpu(hdr->hdr.length) != skb->len ||
            HDR_CMDID(hdr) != HGIC_CMD_GET_FW_INFO - HGIC_CMD_START)
            error = -EPERM;
        else {
            ctrl->attach_tx_consumed = true;
            ctrl->attach_skb = NULL;
        }
    }
    spin_unlock_irqrestore(&ctrl->lock, flags);
    if (error)
        hgic_attach_error(error, HGIC_ATTACH_TX_ADMIT);
    return error;
}

static inline int hgic_ctrl_reply_status(const u8 *data, size_t len,
                                       u8 type, u8 ifidx, u16 opcode,
                                       u16 cookie, int *status)
{
    const size_t payload = sizeof(struct hgic_ctrl_hdr);
    u16 actual_opcode;
    int value;

    if (!status || !hgic_ctrl_frame_valid(data, len) ||
        (type != HGIC_HDR_TYPE_CMD && type != HGIC_HDR_TYPE_CMD2) ||
        data[2] != type || (data[3] & 0x0f) != ifidx ||
        ifidx != HGIC_WDEV_ID_STA ||
        get_unaligned((const u16 *)(data + 6)) != cookie)
        return -EPROTO;
    actual_opcode = type == HGIC_HDR_TYPE_CMD ? data[8] :
                    get_unaligned_le16(data + 8);
    if (actual_opcode != opcode)
        return -EPROTO;
    value = (s16)get_unaligned_le16(data + offsetof(struct hgic_ctrl_hdr, cmd.status));
    if (opcode == HGIC_CMD_GET_FW_INFO - HGIC_CMD_START && value >= 0 &&
        (value != 24 || !hgic_ctrl_retail_info_valid(data + payload, len - payload)))
        return -EPROTO;
    *status = value;
    return 0;
}

static inline int hgic_ctrl_reply_copy(const u8 *data, size_t len,
                                     u8 type, u8 ifidx, u16 opcode, u16 cookie,
                                     u8 *out, size_t capacity)
{
    int value, error;

    if (!out && capacity)
        return -EINVAL;
    error = hgic_ctrl_reply_status(data, len, type, ifidx, opcode, cookie, &value);
    if (error)
        return error;
    /* Setters/scalar replies may return a positive scalar without payload.
     * Only a caller requesting bytes treats positive status as a byte count.
     * Negative status is returned intact; never copy even bounded error data.
     */
    if (value > 0 && out) {
        if ((size_t)value != len - sizeof(struct hgic_ctrl_hdr) ||
            (size_t)value > capacity)
            return -EMSGSIZE;
        memcpy(out, data + sizeof(struct hgic_ctrl_hdr), value);
    }
    return value;

struct ieee80211_hw *ieee80211_alloc_hw_nm(size_t priv_data_len,
					   const struct ieee80211_ops *ops,
					   const char *requested_name)
{
	struct ieee80211_local *local;
	int priv_size, i;
	struct wiphy *wiphy;
	bool emulate_chanctx;

	if (WARN_ON(!ops->tx || !ops->start || !ops->stop || !ops->config ||
		    !ops->add_interface || !ops->remove_interface ||
		    !ops->configure_filter || !ops->wake_tx_queue))
		return NULL;

	if (WARN_ON(ops->sta_state && (ops->sta_add || ops->sta_remove)))
		return NULL;

	if (WARN_ON(!!ops->link_info_changed != !!ops->vif_cfg_changed ||
		    (ops->link_info_changed && ops->bss_info_changed)))
		return NULL;

	/* check all or no channel context operations exist */
	if (ops->add_chanctx == ieee80211_emulate_add_chanctx &&
	    ops->remove_chanctx == ieee80211_emulate_remove_chanctx &&
	    ops->change_chanctx == ieee80211_emulate_change_chanctx) {
		if (WARN_ON(ops->assign_vif_chanctx ||
			    ops->unassign_vif_chanctx))
			return NULL;
		emulate_chanctx = true;
	} else {
		if (WARN_ON(ops->add_chanctx == ieee80211_emulate_add_chanctx ||
			    ops->remove_chanctx == ieee80211_emulate_remove_chanctx ||
			    ops->change_chanctx == ieee80211_emulate_change_chanctx))
			return NULL;
		if (WARN_ON(!ops->add_chanctx ||
			    !ops->remove_chanctx ||
			    !ops->change_chanctx ||
			    !ops->assign_vif_chanctx ||
			    !ops->unassign_vif_chanctx))
			return NULL;
		emulate_chanctx = false;
	}

	result = wiphy_register(local->hw.wiphy);
	if (result < 0)
		goto fail_wiphy_register;

	debugfs_hw_add(local);
	rate_control_add_debugfs(local);

	ieee80211_check_wbrf_support(local);

	rtnl_lock();
	wiphy_lock(hw->wiphy);

	/* add one default STA interface if supported */
	if (local->hw.wiphy->interface_modes & BIT(NL80211_IFTYPE_STATION) &&
	    !ieee80211_hw_check(hw, NO_AUTO_VIF)) {
		struct vif_params params = {0};

		result = ieee80211_if_add(local, "wlan%d", NET_NAME_ENUM, NULL,
					  NL80211_IFTYPE_STATION, &params);
		if (result)
			wiphy_warn(local->hw.wiphy,
				   "Failed to add default virtual iface\n");
	}

	wiphy_unlock(hw->wiphy);
	rtnl_unlock();

#ifdef CONFIG_INET
	local->ifa_notifier.notifier_call = ieee80211_ifa_changed;
	result = register_inetaddr_notifier(&local->ifa_notifier);
	if (result)
		goto fail_ifa;
#endif

#if IS_ENABLED(CONFIG_IPV6)
	local->ifa6_notifier.notifier_call = ieee80211_ifa6_changed;
	result = register_inet6addr_notifier(&local->ifa6_notifier);
	if (result)
		goto fail_ifa6;
#endif

	return 0;

int (*add_chanctx)(struct ieee80211_hw *hw,
		   struct ieee80211_chanctx_conf *ctx);
void (*remove_chanctx)(struct ieee80211_hw *hw,
		       struct ieee80211_chanctx_conf *ctx);
void (*change_chanctx)(struct ieee80211_hw *hw,
		       struct ieee80211_chanctx_conf *ctx,
		       u32 changed);
int (*assign_vif_chanctx)(struct ieee80211_hw *hw,
			  struct ieee80211_vif *vif,
			  struct ieee80211_bss_conf *link_conf,
			  struct ieee80211_chanctx_conf *ctx);
void (*unassign_vif_chanctx)(struct ieee80211_hw *hw,
			     struct ieee80211_vif *vif,
			     struct ieee80211_bss_conf *link_conf,
			     struct ieee80211_chanctx_conf *ctx);

	/* Notify protocols, that a new device appeared. */
	netdev_lock_ops(dev);
	ret = call_netdevice_notifiers(NETDEV_REGISTER, dev);
	netdev_unlock_ops(dev);
	ret = notifier_to_errno(ret);
	if (ret) {
		/* Expect explicit free_netdev() on failure */
		dev->needs_free_netdev = false;
		unregister_netdevice_queue(dev, NULL);
		goto out;
	}
	/*
	 *	Prevent userspace races by waiting until the network
	 *	device is fully setup before sending notifications.
	 */
	if (!(dev->rtnl_link_ops && dev->rtnl_link_initializing))
		rtmsg_ifinfo(RTM_NEWLINK, dev, ~0U, GFP_KERNEL, 0, NULL);

out:
	return ret;

err_uninit_notify:
	call_netdevice_notifiers(NETDEV_PRE_UNINIT, dev);
err_ifindex_release:
	dev_index_release(net, dev->ifindex);
err_free_pcpu:
	netdev_do_free_pcpu_stats(dev);
err_uninit:
	if (dev->netdev_ops->ndo_uninit)
		dev->netdev_ops->ndo_uninit(dev);

void unregister_netdevice_many_notify(struct list_head *head,
				      u32 portid, const struct nlmsghdr *nlh)
{
	struct net_device *dev, *tmp;
	LIST_HEAD(close_head);
	int cnt = 0;

	BUG_ON(dev_boot_phase);
	ASSERT_RTNL();

	if (list_empty(head))
		return;

	list_for_each_entry_safe(dev, tmp, head, unreg_list) {
		/* Some devices call without registering
		 * for initialization unwind. Remove those
		 * devices and proceed with the remaining.
		 */
		if (dev->reg_state == NETREG_UNINITIALIZED) {
			pr_debug("unregister_netdevice: device %s/%p never was registered\n",
				 dev->name, dev);

			WARN_ON(1);
			list_del(&dev->unreg_list);
			continue;
		}
		dev->dismantle = true;
		BUG_ON(dev->reg_state != NETREG_REGISTERED);
	}

	/* If device is running, close it first. Start with ops locked... */
	list_for_each_entry(dev, head, unreg_list) {
		if (!(dev->flags & IFF_UP))
			continue;
		if (netdev_need_ops_lock(dev)) {
			list_add_tail(&dev->close_list, &close_head);
			netdev_lock(dev);
		}
		netif_close_many_and_unlock_cond(&close_head);
	}
	netif_close_many_and_unlock(&close_head);
	/* ... now go over the rest. */
	list_for_each_entry(dev, head, unreg_list) {
		if (!netdev_need_ops_lock(dev))
			list_add_tail(&dev->close_list, &close_head);
	}
	netif_close_many(&close_head, true);

	list_for_each_entry(dev, head, unreg_list) {
		/* And unlink it from device chain. */
		unlist_netdevice(dev);
		netdev_lock(dev);
		WRITE_ONCE(dev->reg_state, NETREG_UNREGISTERING);
		netdev_unlock(dev);
	}
	flush_all_backlogs();

	synchronize_net();

	list_for_each_entry(dev, head, unreg_list) {
		struct sk_buff *skb = NULL;

		/* Shutdown queueing discipline. */
		netdev_lock_ops(dev);
		dev_shutdown(dev);
		dev_tcx_uninstall(dev);
		dev_xdp_uninstall(dev);
		dev_memory_provider_uninstall(dev);
		netdev_unlock_ops(dev);
		bpf_dev_bound_netdev_unregister(dev);

		netdev_offload_xstats_disable_all(dev);

		/* Notify protocols, that we are about to destroy
		 * this device. They should clean all the things.
		 */
		call_netdevice_notifiers(NETDEV_UNREGISTER, dev);

		if (!(dev->rtnl_link_ops && dev->rtnl_link_initializing))
			skb = rtmsg_ifinfo_build_skb(RTM_DELLINK, dev, ~0U, 0,
						     GFP_KERNEL, NULL, 0,
						     portid, nlh);

		/*
		 *	Flush the unicast and multicast chains
		 */
		dev_uc_flush(dev);
		dev_mc_flush(dev);

		netdev_name_node_alt_flush(dev);
		netdev_name_node_free(dev->name_node);

		netdev_rss_contexts_free(dev);

		call_netdevice_notifiers(NETDEV_PRE_UNINIT, dev);

		if (dev->netdev_ops->ndo_uninit)

		ret = cfg80211_register_netdevice(ndev);
		if (ret) {
			free_netdev(ndev);
			return ret;
		}
	}

	mutex_lock(&local->iflist_mtx);
	list_add_tail_rcu(&sdata->list, &local->interfaces);
	mutex_unlock(&local->iflist_mtx);

	if (new_wdev)
		*new_wdev = &sdata->wdev;

	return 0;
}

void ieee80211_if_remove(struct ieee80211_sub_if_data *sdata)
{
	ASSERT_RTNL();
	lockdep_assert_wiphy(sdata->local->hw.wiphy);

	mutex_lock(&sdata->local->iflist_mtx);
	list_del_rcu(&sdata->list);
	mutex_unlock(&sdata->local->iflist_mtx);

	if (sdata->vif.txq)
		ieee80211_txq_purge(sdata->local, to_txq_info(sdata->vif.txq));

	synchronize_rcu();

	cfg80211_unregister_wdev(&sdata->wdev);
